"""Command-line interface for PropScan."""

import click
import json
import sys
from tabulate import tabulate
from colorama import init, Fore, Style

from .core import PropScan


init(autoreset=True)


def format_table_output(results):
    """Format results as a table."""
    if not results:
        click.echo(f"{Fore.GREEN}✓ No proprietary software found!")
        return

    click.echo(f"{Fore.YELLOW}⚠ Proprietary software detected:")
    click.echo()

    for manager_name, packages in results.items():
        click.echo(f"{Fore.CYAN}{Style.BRIGHT}[{manager_name}]")

        table_data = []
        for package in packages:
            table_data.append([
                package["name"],
                package["display_name"],
                package["version"]
            ])

        headers = ["Package Name", "Display Name", "Version"]
        click.echo(tabulate(table_data, headers=headers, tablefmt="grid"))
        click.echo()


def format_json_output(results):
    """Format results as JSON."""
    output = {
        "scan_results": results,
        "total_proprietary": sum(len(packages) for packages in results.values()),
        "managers_scanned": list(results.keys())
    }
    click.echo(json.dumps(output, indent=2))


def format_simple_output(results):
    """Format results as simple text."""
    if not results:
        click.echo("No proprietary software found.")
        return

    click.echo("Proprietary software detected:")
    for manager_name, packages in results.items():
        click.echo(f"\n{manager_name}:")
        for package in packages:
            click.echo(f"  - {package['name']} ({package['version']})")


@click.command()
@click.option(
    "--manager", "-m",
    type=click.Choice(["flatpak", "pacman", "apt", "dnf"], case_sensitive=False),
    help="Scan specific package manager only"
)
@click.option(
    "--format", "-f",
    type=click.Choice(["table", "json", "simple"], case_sensitive=False),
    default="table",
    help="Output format (default: table)"
)
@click.option(
    "--list-managers", "-l",
    is_flag=True,
    help="List available package managers and exit"
)
@click.option(
    "--verbose", "-v",
    is_flag=True,
    help="Enable verbose output"
)
@click.version_option(version="1.0.0", prog_name="PropScan")
def main(manager, format, list_managers, verbose):
    """
    PropScan - Scan for proprietary software on Linux systems.

    Supports Flatpak, Pacman, APT, and DNF package managers.
    """
    scanner = PropScan()

    if list_managers:
        available = scanner.get_available_managers()
        if available:
            click.echo("Available package managers:")
            for mgr in available:
                click.echo(f"  - {mgr.name} ({mgr.command})")
        else:
            click.echo("No supported package managers found.")
        return

    if verbose:
        available = scanner.get_available_managers()
        click.echo(f"Scanning with {len(available)} package manager(s)...")
        for mgr in available:
            click.echo(f"  - {mgr.name}")
        click.echo()

    try:
        results = scanner.scan_all(manager_filter=manager)

        if format == "json":
            format_json_output(results)
        elif format == "simple":
            format_simple_output(results)
        else:  # table
            format_table_output(results)

        # Exit with non-zero code if proprietary software found
        if results:
            sys.exit(1)
        else:
            sys.exit(0)

    except KeyboardInterrupt:
        click.echo(f"\n{Fore.YELLOW}Scan interrupted by user.")
        sys.exit(130)
    except Exception as e:
        click.echo(f"{Fore.RED}Error during scan: {e}", err=True)
        if verbose:
            import traceback
            traceback.print_exc()
        sys.exit(1)


if __name__ == "__main__":
    main()
